import { useState } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Brain, ChevronRight, Play, FlaskConical, Database, Cpu } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

type Model = {
  id: string;
  name: string;
  type: string;
  status: "production" | "training" | "staging" | "planned";
  accuracy?: number;
  dataset: string;
};

const MODELS: Model[] = [
  { id: "m1", name: "Threat Classifier v3", type: "Multi-label NLP", status: "production", accuracy: 94.2, dataset: "threat_items (847K)" },
  { id: "m2", name: "IOC Entity Extractor", type: "NER", status: "production", accuracy: 91.8, dataset: "enriched feeds" },
  { id: "m3", name: "ATT&CK Technique Mapper", type: "Classification", status: "staging", accuracy: 88.5, dataset: "MITRE + briefs" },
  { id: "m4", name: "Phishing Detector", type: "Binary classifier", status: "training", dataset: "email corpus" },
  { id: "m5", name: "Anomaly Scorer (SOC)", type: "Unsupervised", status: "planned", dataset: "alert telemetry" },
  { id: "m6", name: "Fusion Reasoning Agent", type: "LLM chain", status: "production", dataset: "ai-fusion pipeline" },
];

const STATUS_STYLE: Record<Model["status"], string> = {
  production: "bg-emerald-500/15 text-emerald-400 border-emerald-500/30",
  training: "bg-amber-500/15 text-amber-400 border-amber-500/30",
  staging: "bg-blue-500/15 text-blue-400 border-blue-500/30",
  planned: "bg-slate-500/15 text-slate-400 border-slate-500/30",
};

export default function AIResearchLab() {
  const { toast } = useToast();
  const [training, setTraining] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);

  const startTraining = (modelId: string) => {
    setTraining(modelId);
    setProgress(0);
    const interval = setInterval(() => {
      setProgress((p) => {
        if (p >= 100) {
          clearInterval(interval);
          setTraining(null);
          toast({ title: "Training job queued", description: "Model will deploy to staging after validation." });
          return 100;
        }
        return p + 8;
      });
    }, 400);
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
        <ChevronRight className="h-3 w-3" />
        <Link to="/company/ai-research" className="hover:text-cyan-400">AI Research</Link>
        <ChevronRight className="h-3 w-3" />
        <span className="text-fuchsia-400">Model Training Lab</span>
      </div>

      <div className="flex items-start gap-4 mb-8">
        <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-fuchsia-500 to-pink-600">
          <FlaskConical className="h-6 w-6 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">Detection ML Pipeline</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Model registry, training jobs, and deployment staging for security AI research
          </p>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-3 mb-8">
        {[
          { icon: Brain, label: "Models in production", value: MODELS.filter((m) => m.status === "production").length },
          { icon: Database, label: "Training datasets", value: 6 },
          { icon: Cpu, label: "GPU jobs this week", value: training ? 1 : 0 },
        ].map(({ icon: Icon, label, value }) => (
          <Card key={label}>
            <CardContent className="pt-5 flex items-center gap-3">
              <Icon className="h-8 w-8 text-fuchsia-400/70" />
              <div>
                <p className="text-2xl font-bold">{value}</p>
                <p className="text-xs text-muted-foreground">{label}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {training && (
        <Card className="mb-6 border-amber-500/30 bg-amber-500/5">
          <CardContent className="py-4">
            <p className="text-sm font-medium text-amber-300 mb-2">Training in progress…</p>
            <Progress value={progress} className="h-2" />
          </CardContent>
        </Card>
      )}

      <div className="grid gap-4 md:grid-cols-2">
        {MODELS.map((m) => (
          <Card key={m.id}>
            <CardHeader className="pb-2 flex flex-row items-start justify-between">
              <CardTitle className="text-base">{m.name}</CardTitle>
              <Badge variant="outline" className={STATUS_STYLE[m.status]}>{m.status}</Badge>
            </CardHeader>
            <CardContent className="space-y-2 text-sm">
              <p className="text-muted-foreground">{m.type}</p>
              <p className="text-xs"><span className="text-slate-500">Dataset:</span> {m.dataset}</p>
              {m.accuracy != null && (
                <p className="text-xs"><span className="text-slate-500">Accuracy:</span> {m.accuracy}%</p>
              )}
              {(m.status === "planned" || m.status === "staging") && (
                <Button
                  size="sm"
                  variant="outline"
                  className="mt-2"
                  disabled={!!training}
                  onClick={() => startTraining(m.id)}
                >
                  <Play className="h-3.5 w-3.5 mr-1" /> Start training job
                </Button>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}
